'use client';

import { CessionarioMetricsGrid } from '@/components/Juridico/Details/CessionarioMetricsGrid';
import { ExtratoCessionarioEditModal } from '@/components/Juridico/Details/ExtratoCessionarioEditModal';
import { FinancePartyCard } from '@/components/Juridico/Details/finance/_components/FinancePartyCard';
import { JuridicoCommonDialog } from '@/components/Modals/Juridico/JuridicoCommonDialog';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ProductDialogDataField, productDialogOutlineButtonClass } from '@/design-system';
import { maskCpfCnpj } from '@/functions/formaters/maskPii';
import {
    canEditExtratoCessionarioLink,
    normalizeExtratoCessionarioPercentual,
    resolveExtratoCessionarioUnlinkId,
} from '@/functions/due-diligence/resolve-due-investidores';
import { resolvePctAquisicaoInvestidorDisplay } from '@/services/cessionario-vinculado';
import { useExtratoCessionarioUnlinkMutation } from '@/hooks/mutations/useExtratoCessionarioMutations';
import { OficioLinkedCedente } from '@/types/oficio';
import { LoaderCircle, PencilLine, Trash2, User } from 'lucide-react';

interface ExtratoCessionarioManageCardProps {
    link: OficioLinkedCedente;
    extratoId: string;
    dueId?: string;
    isLocked?: boolean;
    layout?: 'investidor' | 'finance';
}

function formatPercentualDisplay(value: string | number | null | undefined): string {
    const normalized = normalizeExtratoCessionarioPercentual(value, 'extrato');
    if (normalized === null || normalized === undefined || normalized === '') return '—';
    const numeric = Number(normalized);
    if (Number.isNaN(numeric)) return String(normalized);
    return `${numeric.toLocaleString('pt-BR', { maximumFractionDigits: 2 })}%`;
}

function formatDelimitadorDisplay(link: OficioLinkedCedente): string {
    if (!link.delimitador_ativo) return 'Desativado';
    if (link.delimitador_percentual == null || link.delimitador_percentual === '') {
        return 'Ativo (sem teto)';
    }
    return formatPercentualDisplay(link.delimitador_percentual);
}

