import { describe, expect, it, jest } from '@jest/globals';
import '@testing-library/jest-dom/jest-globals';
import { render, screen, within } from '@testing-library/react';
import type { OficioLinkedCedente } from '@/types/oficio';
import { CedenteSwitcher } from '../CedenteSwitcher';

function makeCedenteItem({
    id,
    nome,
    processosConcluidos,
    certidoesConcluidas,
}: {
    id: string;
    nome: string;
    processosConcluidos: boolean;
    certidoesConcluidas: boolean;
}): OficioLinkedCedente {
    return {
        id: `relation-${id}`,
        percentual_cessao: '50',
        criado_em: '2026-01-01T00:00:00Z',
        cedente: {
            id,
            tipo: 'PF',
            nome,
            documento: '111.111.111-11',
            informacoes_bancarias: { banco: '', agencia: '', conta: '', pix: '' },
            tipo_do_cedente: 'CEDENTE',
            divida_fiscal: 0,
            divida_processual: 0,
            parecer: {
                processos: {
                    processo_status: null,
                    descricao_processos: '',
                    processos_flags: [],
                },
                certidao: {
                    certidao_status: null,
                    descricao_certidao: '',
                    certidoes_flags: [],
                },
            },
            processos_concluidos: processosConcluidos,
            certidoes_concluidas: certidoesConcluidas,
        },
    };
}

function renderCedenteSwitcher(cedentesState: OficioLinkedCedente[]) {
    render(
        <CedenteSwitcher
            cedentesState={cedentesState}
            activeCedente={0}
            cessaoPercentualResumo={null}
            onSetActiveCedente={jest.fn()}
            onAddCedente={jest.fn()}
            onLinkExistingCedente={jest.fn()}
            onRemoveCedente={jest.fn()}
        />,
    );

