import { Metadata } from 'next';
import { LegalDetails } from '@/components/Juridico/Details';

export const metadata: Metadata = {
    title: 'CelerApp | Comercial',
    description:
        'Ecossistema de amostragem e manipulação dos precatórios por parte do time comercial da Ativos.',
};

export default async function ComercialItemPage({
    params,
}: {
    params: Promise<{ id: string }>;
}) {
    const { id } = await params;
    return <LegalDetails id={id} />;
}

